import random

def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'
    if n == 2:
        return 'C'
    me = [h[0] for h in history]
    op = [h[1] for h in history]
    last_op = op[-1]
    last_me = me[-1]
    op_c = op.count('C')
    op_d = n - op_c
    op_rate = op_c / n

    if n >= 97:
        if op_rate > 0.75:
            return 'D'
        return 'C'
    if n >= 92:
        if op_rate > 0.85:
            return 'D'
        if last_op == 'D':
            return 'D'
        return 'C'

    if n >= 3 and op[-1] == 'D' and op[-2] == 'D' and me[-1] == 'D' and me[-2] == 'D':
        if n >= 4 and op[-3] == 'D' and op[-4] == 'D':
            return 'C'
        if rng.random() < 0.35:
            return 'C'

    if n >= 6:
        recent = op[-6:]
        rc = recent.count('C')
        rd = 6 - rc
        if rd >= 5:
            if rng.random() < 0.05:
                return 'C'
            return 'D'
        if op_rate < 0.25 and rc <= 1:
            return 'D'

    if last_op == 'D':
        if last_me == 'C':
            return 'D'
        streak = 0
        for a in reversed(op):
            if a == 'D':
                streak += 1
            else:
                break
        if streak >= 3 and rng.random() < 0.15:
            return 'C'
        return 'D'

    if n >= 10:
        w = min(15, n)
        recent_c = op[-w:].count('C')
        rr = recent_c / w
        if rr < 0.35:
            if rng.random() < 0.8:
                return 'D'
            return 'C'
        if rr > 0.92 and op_rate > 0.8:
            if rng.random() < 0.06:
                return 'D'
            return 'C'

    if n >= 25 and op_rate > 0.85:
        my_d = me.count('D')
        if my_d < 3 and rng.random() < 0.05:
            return 'D'
        return 'C'

    if last_me == 'D' and last_op == 'C':
        return 'C'

    return 'C'
